import { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { Menu, X } from 'lucide-react';
import { AnimatePresence, motion } from 'framer-motion';

export default function Navbar() {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const location = useLocation();

  const links = [
    { path: '/', label: 'Platform' },
    { path: '/compare', label: 'Compare' },
    { path: '/docs', label: 'Docs' },
    { path: '/changelog', label: 'Changelog' },
    { path: '/research', label: 'Research' }
  ];

  return (
    <>
      <div className="fixed top-0 left-0 right-0 z-50 flex flex-col">
        {/* SUBTLE MARQUEE BANNER */}
        <div className="bg-[#0A0A0A] text-white/40 overflow-hidden whitespace-nowrap py-2.5 border-b border-white/5">
          <div className="animate-[marquee_30s_linear_infinite] inline-block font-mono text-[10px] uppercase tracking-[0.25em]">
            <span className="mx-8"><span className="text-[#34d399]">v0.5.0:</span> Duo Mode, Symphony, TOON Encoder, Durable Snapshots — now open source.</span>
            <span className="mx-8"><span className="text-[#34d399]">v0.5.0:</span> Duo Mode, Symphony, TOON Encoder, Durable Snapshots — now open source.</span>
            <span className="mx-8"><span className="text-[#34d399]">v0.5.0:</span> Duo Mode, Symphony, TOON Encoder, Durable Snapshots — now open source.</span>
            <span className="mx-8"><span className="text-[#34d399]">v0.5.0:</span> Duo Mode, Symphony, TOON Encoder, Durable Snapshots — now open source.</span>
            <span className="mx-8"><span className="text-[#34d399]">v0.5.0:</span> Duo Mode, Symphony, TOON Encoder, Durable Snapshots — now open source.</span>
            <span className="mx-8"><span className="text-[#34d399]">v0.5.0:</span> Duo Mode, Symphony, TOON Encoder, Durable Snapshots — now open source.</span>
          </div>
        </div>

        <nav className="px-6 md:px-16 h-20 flex justify-between items-center bg-[#050505]/90 backdrop-blur-md border-b border-white/5">
          <div className="flex items-center gap-12">
            <Link to="/" className="flex items-center gap-4 group" onClick={() => setMobileMenuOpen(false)}>
            <div className="relative w-8 h-8 flex items-center justify-center">
              <motion.div
                className="absolute inset-0 rounded-full border border-white/40"
                animate={{ scale: [1, 2.5], opacity: [0.8, 0] }}
                transition={{ duration: 2.5, repeat: Infinity, ease: "easeOut" }}
              />
              <motion.div
                className="absolute inset-0 rounded-full border border-white/20"
                animate={{ scale: [1, 2.5], opacity: [0.8, 0] }}
                transition={{ duration: 2.5, repeat: Infinity, ease: "easeOut", delay: 1.25 }}
              />
              <div className="relative z-10 w-8 h-8 flex items-center justify-center border-2 border-white rounded-full bg-[#050505] group-hover:bg-white transition-colors duration-500">
                <div className="w-2.5 h-2.5 bg-white rounded-full group-hover:bg-[#050505] transition-colors duration-500 shadow-[0_0_8px_rgba(255,255,255,0.8)]" />
              </div>
            </div>
            <span className="text-[22px] font-serif italic font-medium tracking-tight text-white relative">
              Aura
              <motion.span 
                className="absolute -inset-2 bg-white/5 blur-md rounded-full z-[-1]"
                animate={{ opacity: [0, 1, 0] }}
                transition={{ duration: 3, repeat: Infinity, ease: "easeInOut" }}
              />
            </span>
          </Link>
        </div>

        <div className="flex items-center gap-8 pointer-events-auto">
          <div className="hidden md:flex gap-8 text-[12px] font-mono uppercase tracking-widest text-white/50">
            {links.map((link) => (
              <Link 
                key={link.path} 
                to={link.path} 
                className={`transition-colors ${location.pathname === link.path ? 'text-white font-bold' : 'hover:text-white'}`}
              >
                {link.label}
              </Link>
            ))}
          </div>

          <button 
            className="md:hidden text-white p-2"
            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
          >
            {mobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
          </button>
        </div>
      </nav>
      </div>

      {/* Mobile Menu Overlay */}
      <AnimatePresence>
        {mobileMenuOpen && (
          <motion.div 
            initial={{ opacity: 0, y: -20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -20 }}
            transition={{ duration: 0.2 }}
            className="fixed inset-0 z-40 bg-[#050505] pt-24 px-6 md:hidden flex flex-col h-screen"
          >
            <div className="flex flex-col gap-8 mt-12">
              {links.map((link) => (
                <Link 
                  key={link.path} 
                  to={link.path} 
                  onClick={() => setMobileMenuOpen(false)}
                  className={`text-[24px] font-serif tracking-tight border-b border-white/10 pb-4 ${location.pathname === link.path ? 'text-white' : 'text-white/50'}`}
                >
                  {link.label}
                </Link>
              ))}
            </div>

            <div className="mt-auto mb-12 flex items-center gap-4 text-[12px] font-mono text-white/50 uppercase tracking-widest">
              <span className="w-2 h-2 bg-white rounded-full animate-pulse" /> Aura v0.5.0
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </>
  );
}
